def count_catalog_employee_packs(session) -> int:
    """Catalog 库内 employee_pack 条目总数（含市场/工作流包，可大于编制数）。"""
    return int(
        session.query(_facade().func.count(_facade().CatalogItem.id))
        .filter(_facade().CatalogItem.artifact == "employee_pack")
        .scalar()
        or 0
    )


